Given an integer n. Print first n elements of Recaman’s sequence. Recaman's Sequence starts with 0 as the first term. For each next term, calculate previous term - index (if positive and not already in sequence); otherwise, use previous term + index.Examples: Input: n = 6Output: 0, 1, 3, 6, 2, 7Explanation: According to Recaman's Sequence:0 (first term)0 - 1 is negative, so use 0 + 1 = 11 - 2 is negative, so use 1 + 2 = 33 - 3 is 0, already in sequence, so use 3 + 3 = 66 - 4 = 2 (not in sequence, so use it)2 - 5 is negative, so use 2 + 5 = 7Input: n = 17Output: 0, 1, 3, 6, 2, 7, 13, 20, 12, 21, 11, 22, 10, 23, 9, 24, 8Try It YourselfTable of Content[Brute Force Approach] Using 2 Nested Loops - O(n^2) Time and O(1) Space[Expected Approach] Using Hashing - O(n) Time and O(n) Space[Brute Force Approach] Using 2 Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to generate the first n terms of Recaman’s sequence by following its recurrence rule. We start with 0 and iteratively compute the next term as previous term - index if it is positive and not already in sequence; otherwise, we use previous term + index. 
            C++

    // C++ Code to print first n terms 
// in Recaman's sequence using 
// BruteForce Approach
#include <bits/stdc++.h>
using namespace std;

// Function to generate Recaman's sequence
vector<int> recamanSequence(int n) {
    vector<int> res(n); 
    res[0] = 0;

    // Generate the sequence
    for (int i = 1; i < n; i++) {

        // Calculate previous term - index
        int curr = res[i - 1] - i;

        // Check if curr is valid and 
        // not in sequence
        bool exists = false;
        for (int j = 0; j < i; j++) {
            if (res[j] == curr) {
                exists = true;
                break;
            }
        }

        // If curr is invalid, use 
        // previous term + index
        if (curr < 0 || exists) {
            curr = res[i - 1] + i;
        }

        res[i] = curr; 
    }

    return res;
}

int main() {
    int n = 6; 
    vector<int> res = recamanSequence(n);

    for (int x : res) {
        cout << x << " ";
    }

    return 0;
}


