[Expected Approach] Using Hashing - O(n) Time and O(n) SpaceThe idea is to construct Recaman's sequence efficiently by using hashing to track visited numbers. The approach iterates from 1 to n, computing a candidate value as the previous term minus the index. If this candidate is negative or already exists in seen, we instead add the index. This ensures each number is unique while following the sequence rules.
            C++

    // C++ Code to print first n terms  
// in Recaman's sequence using  
// Hashing Approach  
#include <bits/stdc++.h>  
using namespace std;  

// Function to generate Recaman's sequence  
vector<int> recamanSequence(int n) {  
    unordered_set<int> s;  
    vector<int> res(n);  
    res[0] = 0;  
    s.insert(0);  

    // Generate the sequence  
    for (int i = 1; i < n; i++) {  

        // Calculate previous term - index  
        int curr = res[i - 1] - i;  

        // If curr is invalid, use  
        // previous term + index  
        if (curr < 0 || s.count(curr)) {  
            curr = res[i - 1] + i;  
        }  

        res[i] = curr;  
        s.insert(curr);  
    }  
    return res;  
}  

int main() {  
    int n = 6;   
    vector<int> res = recamanSequence(n);  
    for (int num : res) {  
        cout << num << " ";  
    }  
    cout << endl;  
    return 0;  
}


