    static int[] RecamanSequence(int n) {
        HashSet<int> s = new HashSet<int>();
        int[] res = new int[n];
        res[0] = 0;
        s.Add(0);

        // Generate the sequence
        for (int i = 1; i < n; i++) {
            // Calculate previous term - index
            int curr = res[i - 1] - i;

            // If curr is invalid, use previous term + index
            if (curr < 0 || s.Contains(curr)) {
                curr = res[i - 1] + i;
            }

            res[i] = curr;
